    sessions.delete(session.id);
    return json({ ok: true }, 200, request, {
      "Set-Cookie": `${COOKIE_NAME}=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0`,
    });
  }

  return safeError("That page is not available.", 404, request);
}

