    for (const record of s.recovery.hashes) {
      if (await recoveryMatches(record, code)) found = true;
    }
    if (!found) {
      s.recoveryAttempts = (s.recoveryAttempts || 0) + 1;
      if (s.recoveryAttempts >= MAX) {
