    const n = B32.indexOf(char);
    if (n < 0) throw new Error("Invalid base32 value");
    bits += n.toString(2).padStart(5, "0");
  }
  const output: number[] = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) output.push(parseInt(bits.slice(i, i + 8), 2));
