 const finder=(r,c)=>{for(let y=-1;y<=7;y++)for(let x=-1;x<=7;x++)set(r+y,c+x,y>=0&&y<=6&&x>=0&&x<=6&&(y===0||y===6||x===0||x===6||(y>=2&&y<=4&&x>=2&&x<=4)))};
 finder(0,0);finder(n-7,0);finder(0,n-7);
 const align=(r,c)=>{for(let y=-2;y<=2;y++)for(let x=-2;x<=2;x++)set(r+y,c+x,Math.max(Math.abs(x),Math.abs(y))!==1)};
 align(6,24);align(24,6);align(24,24);align(24,42);align(42,24);align(42,42);
 for(let i=8;i<n-8;i++){if(m[i][6]===null)set(i,6,i%2===0);if(m[6][i]===null)set(6,i,i%2===0)}set(n-8,8,true);
 const bytes=[...new TextEncoder().encode(text)],bits=[];const put=(v,l)=>{for(let i=l-1;i>=0;i--)bits.push((v>>i)&1)};put(4,4);put(bytes.length,8);bytes.forEach(x=>put(x,8));while(bits.length<1552&&bits.length%8)bits.push(0);
 const data=[];for(let i=0;i<bits.length;i+=8)data.push(bits.slice(i,i+8).reduce((a,b)=>a*2+b,0));let pad=0;while(data.length<194)data.push(pad++%2?0x11:0xec);
 const exp=[],log=[];let x=1;for(let i=0;i<255;i++){exp[i]=x;log[x]=i;x<<=1;if(x&256)x^=285}for(let i=255;i<512;i++)exp[i]=exp[i-255];
 const mul=(a,b)=>a&&b?exp[log[a]+log[b]]:0;let gen=[1];for(let i=0;i<24;i++){const q=Array(gen.length+1).fill(0);for(let j=0;j<gen.length;j++){q[j]^=gen[j];q[j+1]^=mul(gen[j],exp[i])}gen=q}
 const ecc=block=>{const r=Array(24).fill(0);for(const d of block){const f=d^r.shift();r.push(0);for(let j=0;j<24;j++)r[j]^=mul(gen[j+1],f)}return r};
 const blocks=[data.slice(0,97),data.slice(97)], ec=blocks.map(ecc),stream=[];for(let i=0;i<97;i++)for(const b of blocks)stream.push(b[i]);for(let i=0;i<24;i++)for(const e of ec)stream.push(e[i]);
 const db=[];stream.forEach(v=>{for(let i=7;i>=0;i--)db.push((v>>i)&1)});let k=0,up=true;
 for(let c=n-1;c>0;c-=2){if(c===6)c--;for(let z=0;z<n;z++){const r=up?n-1-z:z;for(let j=0;j<2;j++)if(m[r][c-j]===null){let v=db[k++]||0;if((r+c-j)%2===0)v^=1;set(r,c-j,!!v)}}up=!up}
 let d=(1<<3)|0, v=d;while(v>=1<<10)v^=0x537<<(Math.floor(Math.log2(v))-10);const format=((d<<10)|v)^0x5412;
 for(let i=0;i<15;i++){const bit=!!((format>>i)&1);if(i<6)set(i,8,bit);else if(i<8)set(i+1,8,bit);else set(n-15+i,8,bit);if(i<8)set(8,n-i-1,bit);else if(i<9)set(8,15-i,bit);else set(8,15-i-1,bit)}
 out.innerHTML=m.flat().map(v=>'<i class="'+(v?'b':'')+'"></i>').join('');
}
