const B32 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

const origins = new Set([
  `https://localhost:${PORT}`,
  `https://127.0.0.1:${PORT}`,
  `https://[::1]:${PORT}`
]);

