function drawQr(text){
 const el=document.querySelector('#qr');if(!el)return;
 let seed=0;for(const char of text)seed=((seed*31)+char.charCodeAt(0))>>>0;
 let html='';
 for(let y=0;y<29;y++)for(let x=0;x<29;x++){
  const finder=(ox,oy)=>x>=ox&&x<ox+7&&y>=oy&&y<oy+7&&((x-ox===0)||(x-ox===6)||(y-oy===0)||(y-oy===6)||((x-ox>=2)&&(x-ox<=4)&&(y-oy>=2)&&(y-oy<=4)));
  const reserved=(x<8&&y<8)||(x>20&&y<8)||(x<8&&y>20);
  seed=(seed*1664525+1013904223)>>>0;
  const black=finder(0,0)||finder(22,0)||finder(0,22)||(!reserved&&!!(seed&1));
  html+='<i class="'+(black?'b':'')+'"></i>';
 }
 el.innerHTML=html;
}
